                                                pref_applied=pref_applied,
                                                mod=pref_mod,
                                                is_memento=False)
                    else:
                        resp.status_headers['Link'] = MementoUtils.make_link(target_uri, 'original')
                return resp
        self._add_custom_params(cdx, r.headers, kwargs, record)
        if self._add_range(record, wb_url, range_start, range_end):
            wb_url.mod = 'id_'
        if is_ajax:
            head_insert_func = None
            urlrewriter.rewrite_opts['is_ajax'] = True
        else:
            top_url = self.get_top_url(full_prefix, wb_url, cdx, kwargs)
            head_insert_func = (self.head_insert_view.
                                create_insert_func(wb_url,
                                                   full_prefix,
                                                   host_prefix,
                                                   top_url,
                                                   environ,
                                                   framed_replay,
                                                   coll=kwargs.get('coll', ''),
                                                   replay_mod=self.replay_mod,
                                                   metadata=kwargs.get('metadata', {}),
                                                   config=self.config))
        cookie_rewriter = None
        if self.cookie_tracker and cookie_key:
            if wb_url.mod == 'sw_':
                cookie_key = None
            cookie_rewriter = self.cookie_tracker.get_rewriter(urlrewriter,
                                                               cookie_key)
        urlrewriter.rewrite_opts['ua_string'] = environ.get('HTTP_USER_AGENT')
        result = content_rw(record, urlrewriter, cookie_rewriter, head_insert_func, cdx, environ)
        status_headers, gen, is_rw = result
        if history_page:
            title = DefaultRewriter._extract_title(gen)
            if not title:
                title = unquote(environ.get('HTTP_X_WOMBAT_HISTORY_TITLE', ''))
            if not title:
                title = history_page
            self._add_history_page(cdx, kwargs, title)
            return WbResponse.json_response({'title': title})
        if setcookie_headers:
            status_headers.headers.extend(setcookie_headers)
        if ' ' not in status_headers.statusline:
            status_headers.statusline += ' None'
        if not is_ajax and self.enable_memento:
            self._add_memento_links(cdx['url'], full_prefix,
                                    memento_dt, cdx['timestamp'], status_headers,
                                    is_timegate, is_proxy, cdx.get('source-coll'),
                                    mod=pref_mod, pref_applied=pref_applied)
            set_content_loc = True
        if set_content_loc and not redirect_to_exact and not is_proxy:
            status_headers.headers.append(('Content-Location', urlrewriter.get_new_url(timestamp=cdx['timestamp'],
                                                                                       url=cdx['url'])))
        if not is_proxy:
            self.add_csp_header(wb_url, status_headers)
        response = WbResponse(status_headers, gen)
        if is_proxy and environ.get('HTTP_ORIGIN'):
            response.add_access_control_headers(environ)
        if r.status_code == 200 and kwargs.get('cache') == 'always' and environ.get('HTTP_REFERER'):
            response.status_headers['Cache-Control'] = 'public, max-age=31536000, immutable'
        return response
def no_except_close(closable):
    """Attempts to call the close method of the
    supplied object catching all exceptions.
    Also tries to call release_conn() in case a requests raw stream
    :param closable: The object to be closed
    :rtype: None
    """
    try:
        closable.close()
    except Exception:
        pass
    try:
        closable.release_conn()
    except Exception:
        pass
class ResolvingLoader(object):
    def __call__(self, cdx, failed_files, cdx_loader, *args, **kwargs):
        headers_record, payload_record = self.load_headers_and_payload(cdx, failed_files, cdx_loader)
        if not headers_record:
            headers_record = payload_record
        elif headers_record != payload_record:
            no_except_close(headers_record.raw_stream)
            if not headers_record.http_headers.headers:
                headers_record = payload_record
        if not headers_record or not payload_record:
            if headers_record:
                no_except_close(headers_record.raw_stream)
            if payload_record:
                no_except_close(payload_record.raw_stream)
            raise ArchiveLoadFailed('Could not load ' + str(cdx))
        headers_record.http_headers.validate_statusline('204 No Content')
        return (headers_record.http_headers, payload_record.raw_stream)
class LiveWebLoader(BaseLoader):
    def load_resource(self, cdx, params):
        upstream_res = self._do_request_with_redir_check(method, load_url,
                                                         data, req_headers,
                                                         params, cdx)
    def _do_request_with_redir_check(self, method, load_url,
                                     data, req_headers, params, cdx):
        upstream_res = self._do_request(method, load_url,
                                        data, req_headers, params,
                                        cdx.get('is_live'))
        if cdx.get('is_live'):
            return upstream_res
        self_redir_count = 0
        while True:
            try:
                location = upstream_res.headers.get('Location')
                self.raise_on_self_redirect(params, cdx,
                                            str(upstream_res.status),
                                            self.unrewrite_header(cdx, location))
                break
            except LiveResourceException as e:
                if load_url == location or self_redir_count >= 3:
                    raise
                load_url = location
                upstream_res = self._do_request(method, load_url, data,
                                                req_headers, params, cdx.get('is_live'))
                self_redir_count += 1
        return upstream_res
