ARCHIVERS = {
    'tar': TarArchiver,
    'tbz2': lambda dest: TarArchiver(dest, 'bz2'),
    'tar.bz2': lambda dest: TarArchiver(dest, 'bz2'),
    'tar.gz': lambda dest: TarArchiver(dest, 'gz'),
    'tgz': lambda dest: TarArchiver(dest, 'gz'),
    'zip': ZipArchiver,
    'raw': RawArchiver,
}
def restore(restore, restore_as_of, kind, encoding, dest, log=logger.debug):
    """
    Used to restore a file or a directory.
    restore: relative or absolute file or folder to be restored (unquoted)
    restore_as_of: date to restore
    kind: type of archive to generate or raw to stream a single file.
    encoding: encoding of the repository (used to properly encode the filename in archive)
    dest: a filename or a file handler where to write the archive.
    """
    assert isinstance(restore, bytes)
    assert isinstance(restore_as_of, int)
    assert kind in ARCHIVERS
    tmp_output = tempfile.mkdtemp(prefix=b'rdiffweb_restore_')
    log('restoring data into temporary folder: %r' % tmp_output)
    rdiff_backup_path = find_rdiff_backup()
    env = {
        'LANG': LANG,
    }
    if os.environ.get('TMPDIR'):
        env['TMPDIR'] = os.environ['TMPDIR']
    cmd = [
        rdiff_backup_path,
        b'-v',
        b'5',
        b'--restore-as-of=' + str(restore_as_of).encode('latin'),
        restore,
        tmp_output,
    ]
    log('executing %r with env %r' % (cmd, env))
    archive = ARCHIVERS[kind](dest)
    try:
        with popen(cmd, env=env) as output:
            for line in output:
                line = line.rstrip(b'\n')
                log('rdiff-backup: %r' % line)
                if not line.startswith(TOKEN):
                    continue
                value = line[len(TOKEN) :]
                fullpath, arcname = _lookup_filename(tmp_output, line[len(TOKEN) :])
                if not fullpath:
                    log('error: file not found %r' % value)
                    continue
                log('adding %r' % fullpath)
                try:
                    archive.addfile(fullpath, arcname, encoding)
                except Exception:
                    log('error: fail to add %r' % fullpath, exc_info=1)
                if os.path.isfile(fullpath) or os.path.islink(fullpath):
                    os.remove(fullpath)
    finally:
        archive.close()
        if os.path.isdir(tmp_output):
            shutil.rmtree(tmp_output, ignore_errors=True)
        elif os.path.isfile(tmp_output):
            os.remove(tmp_output)
class UserObject(object):
    def add_authorizedkey(self, key, comment=None):
        """
        Add the given key to the user. Adding the key to his `authorized_keys`
        file if it exists and adding it to database.
        """
        assert key
        key = authorizedkeys.check_publickey(key)
        key = authorizedkeys.AuthorizedKey(
            options=None, keytype=key.keytype, key=key.key, comment=comment or key.comment
        )
        filename = os.path.join(self.user_root, '.ssh', 'authorized_keys')
        if os.path.isfile(filename):
            with open(filename, mode="r+", encoding='utf-8') as fh:
                if authorizedkeys.exists(fh, key):
                    raise DuplicateSSHKeyError(_("SSH key already exists"))
                logger.info("add key [%s] to [%s] authorized_keys", key, self.username)
                authorizedkeys.add(fh, key)
        else:
            logger.info("add key [%s] to [%s] database", key, self.username)
            try:
                with self._store.engine.connect() as conn:
                    conn.execute(
                        _SSHKEYS.insert().values(userid=self._userid, fingerprint=key.fingerprint, key=key.getvalue())
                    )
            except IntegrityError:
                raise DuplicateSSHKeyError(
                    _("Duplicate key. This key already exists or is associated to another user.")
                )
        self._store.bus.publish('user_attr_changed', self, {'authorizedkeys': True})
    def delete(self):
        """
        Delete the given user from password store.
        Return True if the user was deleted.
        Return False if the user didn't exists.
        Raise a ValueError when trying to delete the admin user.
        """
        if self.username == self._store._admin_user:
            raise ValueError(_("can't delete admin user"))
        logger.info("deleting user [%s] from database", self.username)
        with self._store.engine.connect() as conn:
            conn.execute(_SSHKEYS.delete(_SSHKEYS.c.userid == self._userid))
            conn.execute(_REPOS.delete(_REPOS.c.userid == self._userid))
            deleted = conn.execute(_USERS.delete(_USERS.c.userid == self._userid))
            assert deleted.rowcount, 'fail to delete user'
        self._store.bus.publish('user_deleted', self.username)
        return True
    def refresh_repos(self, delete=False):
        """
        Return list of repositories object to reflect the filesystem folders.
        Return a RepoObject for each sub directories under `user_root` with `rdiff-backup-data`.
        """
        with self._store.engine.connect() as conn:
            def _onerror(unused):
                logger.error('error updating user [%s] repos' % self.username, exc_info=1)
            dirty = False
            records = list(conn.execute(_REPOS.select(_REPOS.c.userid == self._userid).order_by(_REPOS.c.repopath)))
            user_root = os.fsencode(self.user_root)
            for root, dirs, unused_files in os.walk(user_root, _onerror):
                for name in dirs.copy():
                    if name.startswith(b'.'):
                        dirs.remove(name)
                if b'rdiff-backup-data' in dirs:
                    repopath = os.path.relpath(root, start=user_root)
                    del dirs[:]
                    repopath = b'' if repopath == b'.' else repopath
                    record_match = next(
                        (record for record in records if record['repopath'] == os.fsdecode(repopath)), None
                    )
                    if not record_match:
                        conn.execute(_REPOS.insert().values(userid=self._userid, repopath=os.fsdecode(repopath)))
                        dirty = True
                    else:
                        records.remove(record_match)
                if root.count(SEP) - user_root.count(SEP) >= self._store._max_depth:
                    del dirs[:]
            if delete:
                for record in records:
                    conn.execute(_REPOS.delete(_REPOS.c.repoid == record['repoid']))
        return dirty
    def set_password(self, password, old_password=None):
        """
        Change the user's password. Raise a ValueError if the username or
        the password are invalid.
        """
        assert isinstance(password, str)
        assert old_password is None or isinstance(old_password, str)
        if not password:
            raise ValueError("password can't be empty")
        cfg = self._store.app.cfg
        if cfg.password_min_length > len(password) > cfg.password_max_length:
            raise ValueError("invalid password length")
        if self.username == self._store._admin_user and self._store._admin_password:
            raise ValueError(_("can't update admin-password defined in configuration file"))
        if old_password and not check_password(old_password, self.hash_password):
            raise ValueError(_("Wrong password"))
        logger.info("updating user password [%s]", self.username)
        self.hash_password = hash_password(password)
        self._store.bus.publish('user_password_changed', self)
class Store(SimplePlugin):
    def add_user(self, user, password=None, attrs=None):
        """
        Used to add a new user with an optional password.
        """
        assert password is None or isinstance(password, str)
        if self.get_user(user):
            raise RdiffError(_("User %s already exists." % (user,)))
        logger.info("adding new user [%s]", user)
        with self.engine.connect() as conn:
            inserted = conn.execute(
                _USERS.insert().values(username=user, password=hash_password(password) if password else '')
            )
            assert inserted.rowcount
            record = conn.execute(_USERS.select(_USERS.c.username == user)).fetchone()
        userobj = UserObject(self, record)
        self.bus.publish('user_added', userobj)
        return userobj
    def get_repo(self, name, as_user=None, refresh=False):
        """
        Return the repository identified as `name`.
        `name` should be <username>/<repopath>
        """
        username, repopath = _split_path(name)
        repopath = os.fsdecode(repopath)
        as_user = as_user or self.app.currentuser
        assert as_user, "as_user or current user must be defined"
        if username != as_user.username and not as_user.is_admin:
            raise AccessDeniedError(name)
        user_obj = self.get_user(username)
        if not user_obj:
            raise DoesNotExistError(name)
        return user_obj.get_repo(repopath, refresh=refresh)
    def get_user(self, user):
        """Return a user object."""
        with self.engine.connect() as conn:
            record = conn.execute(_USERS.select(_USERS.c.username == user)).fetchone()
            if record:
                return UserObject(self, record)
        return None
class RdiffRepo(object):
    def __init__(self, user_root, path, encoding):
        if isinstance(user_root, str):
            user_root = os.fsencode(user_root)
        if isinstance(path, str):
            path = os.fsencode(path)
        assert isinstance(user_root, bytes)
        assert isinstance(path, bytes)
        assert encoding
        self._encoding = encodings.search_function(encoding)
        assert self._encoding
        self.path = path.strip(b"/")
        if self.path:
            self.full_path = os.path.normpath(os.path.join(user_root, self.path))
        else:
            self.full_path = os.path.normpath(user_root)
        self._data_path = os.path.join(self.full_path, RDIFF_BACKUP_DATA)
        assert isinstance(self._data_path, bytes)
        self._increment_path = os.path.join(self._data_path, INCREMENTS)
        self.current_mirror = MetadataDict(self, CurrentMirrorEntry)
        self.error_log = MetadataDict(self, LogEntry)
        self.mirror_metadata = MetadataDict(self, MirrorMetadataEntry)
        self.file_statistics = MetadataDict(self, FileStatisticsEntry)
        self.session_statistics = MetadataDict(self, SessionStatisticsEntry)
    def _decode(self, value, errors='replace'):
        """Used to decode a repository path into unicode."""
        assert isinstance(value, bytes)
        return self._encoding.decode(value, errors)[0]
    def fstat(self, path):
        """Return a new instance of DirEntry to represent the given path."""
        assert isinstance(path, bytes)
        full_path = os.path.normpath(os.path.join(self.full_path, path.strip(b'/')))
        increment_path = os.path.normpath(os.path.join(self._increment_path, path.strip(b'/'), b'..'))
        if not full_path.startswith(self.full_path) or not increment_path.startswith(self.full_path):
            raise AccessDeniedError('%s make reference outside the repository' % self._decode(path))
        relative_path = os.path.relpath(full_path, self.full_path)
        if relative_path.startswith(RDIFF_BACKUP_DATA):
            raise DoesNotExistError(path)
        if relative_path == b'.':
            return RdiffDirEntry(self, b'', True, [])
        try:
            os.lstat(full_path)
            exists = True
        except (OSError, ValueError):
            exists = False
        increment_items = os.listdir(increment_path)
        prefix = os.path.basename(full_path)
        entry = RdiffDirEntry(self, relative_path, exists, [])
        for item in increment_items:
            if not item.startswith(prefix):
                continue
            try:
                increment = IncrementEntry(item)
            except ValueError:
                continue
            if increment.name != prefix:
                continue
            bisect.insort_left(entry._increments, increment)
        if not exists and not entry._increments:
            logger.error("path [%r] doesn't exists", path)
            raise DoesNotExistError(path)
        return entry
class SSHKeysPlugin(Controller):
    def _add_key(self, action, form):
        assert action == 'add'
        assert form
        if not form.validate():
            for unused, messages in form.errors.items():
                for message in messages:
                    flash(message, level='warning')
            return
        try:
            self.app.currentuser.add_authorizedkey(key=form.key.data, comment=form.title.data)
        except DuplicateSSHKeyError as e:
            flash(str(e), level='error')
        except Exception:
            flash(_("Unknown error while adding the SSH Key"), level='error')
            _logger.warning("error adding ssh key", exc_info=1)
    def _delete_key(self, action, form):
        assert action == 'delete'
        assert form
        if not form.validate():
            for unused, messages in form.errors.items():
                for message in messages:
                    flash(message, level='warning')
            return
        is_maintainer()
        try:
            self.app.currentuser.delete_authorizedkey(form.fingerprint.data)
        except Exception:
            flash(_("Unknown error while removing the SSH Key"), level='error')
            _logger.warning("error removing ssh key", exc_info=1)
def get_pyinfo():
    try:
        import distro
        yield _('OS Version'), '%s %s (%s %s)' % (
            platform.system(),
            platform.release(),
            distro.name().capitalize(),
            distro.version(),
        )
    except Exception:
        yield _('OS Version'), '%s %s' % (platform.system(), platform.release())
