                            if start < first_size:
                                closest_pos = 0
                            else:
                                closest_pos = (
                                    ((start - first_size) >> 16 << 16)
                                    + first_size
                                )
                            pos = min(closest_pos, max(pdata_map.keys()))
                            data = pdata_map[pos]
                            while data is not None:
                                length = len(data.data)
                                pos = pos + length
                                if pos > start:
                                    lstart = length - (pos - start)
                                    if lstart < 0:
                                        lstart = 0
                                    if end <= pos:
                                        lend = length - (pos - end)
                                        RESPONSE.write(data[lstart:lend])
                                        break
                                    RESPONSE.write(data[lstart:])
                                data = data.next
                                pdata_map[pos] = data
