        unpack_file_url(link, location, download_dir, hashes=hashes)
    else:
        if session is None:
            session = PipSession()
        unpack_http_url(
            link,
            location,
            download_dir,
            session,
            hashes=hashes,
            progress_bar=progress_bar
        )
