    msgs = UserMessage.objects.filter(user_profile=user_profile).extra(
        where=[UserMessage.where_unread()],
    )
    count = msgs.update(
        flags=F("flags").bitor(UserMessage.flags.read),
    )
    event = asdict(
        ReadMessagesEvent(
            messages=[],
            all=True,
        )
    )
    event_time = timezone_now()
