                return serve_fileobj(entry._open(), content_type="text/plain")
            elif entry:
                data = entry.tail()
        except FileNotFoundError:
            pass
        if limit < len(repo_obj.error_log):
            error_logs = repo_obj.error_log[: -limit - 1 : -1]
        else:
            error_logs = repo_obj.error_log
