    return render_template("subjob.html",
                           title=f"Subjob {subjob_id} - Job {job_id}",
                           subjob_info=subjob_info,
                           status_color=status_color,
                           attribute_actions=actions["attributes"],
                           method_actions=actions["methods"],
                           stdout=stdout,
                           stderr=stderr,
                           full_print_info=full_print_info,
                           job_id=job_id,
                           browse_path=browse_path)
@gui.route("/api/jobs/<int:job_id>/subjobs/<int:subjob_id>/<attribute>", methods=["GET"])
@token_required
def subjob_attribute_endpoint(current_api_user, job_id: int, subjob_id: int, attribute: str):
    """
    Given the job id, subjob id and attribute; return the attribute information in the string format via JSON.
    :param job_id: int
    :param subjob_id: int
    :param attribute: str
    :param current_api_user: Information of the current_api_user based on the request's JWT token
    """
    try:
        subjob_attribute_info = query_internal_api(f"/internal/jobs/{job_id}/subjobs/{subjob_id}/{attribute}", "get")
    except Exception as err:
        return jsonify({"success": False, "message": str(err)}), 400
    return jsonify(subjob_attribute_info)
def query_internal_api(route: str, method: str, **kwargs):
    """
    :param route: str
    :param method: str
    :param kwargs: dict
    :return: dict
    Make a HTTP request to the Internal API Flask server which runs on a GangaThread to query data from Ganga.
    Check response status code and extract the data or raise an exception accordingly.
    kwargs can be param, json, etc. Any attribute that is supported by the requests module.
    """
    INTERNAL_URL = f"http://localhost:{gui.config['INTERNAL_PORT']}"
    if method not in ["get", "post", "put", "delete"]:
        raise Exception(f"Unsupported method: {method}")
    res = getattr(requests, method)(INTERNAL_URL + route, **kwargs)
    if res.status_code != 200:
        raise Exception(res.json().get("message"))
    return res.json()
def start_web_cli(host: str, port: int, internal_port: int, log_output=True, ganga_args: str = ""):
    """
    Start the web server on eventlet serving the terminal on the specified port. (Production ready server)
    :param ganga_args: str - arguments to be passed to ganga
    :param host: str
    :param port: int
    :param internal_port: int
    """
    from GangaGUI.start import create_default_user
    gui_user, gui_password = create_default_user()
    print(f"Starting the GUI server on http://{host}:{port}")
    print(f"You login information for the GUI is: Username: {gui_user.user} Password: {gui_password}")
    gui.config["INTERNAL_PORT"] = internal_port
    gui.config["WEB_CLI"] = True
    gui.config["GANGA_ARGS"] = ganga_args
    socketio.run(gui, host=host, port=port, log_output=log_output)

def _pack_arguments(fn_type, args, context):
    args_tuple_t = TupleType([x.typ for x in args])
    args_as_tuple = IRnode.from_list(["multi"] + [x for x in args], typ=args_tuple_t)
    args_abi_t = args_tuple_t.abi_type
    dst_tuple_t = TupleType(
        [new_type_to_old_type(typ) for typ in fn_type.arguments.values()][: len(args)]
    )
    check_assign(dummy_node_for_type(dst_tuple_t), args_as_tuple)
    if fn_type.return_type is not None:
        return_abi_t = calculate_type_for_external_return(fn_type.return_type).abi_type
        buflen = max(args_abi_t.size_bound(), return_abi_t.size_bound())
    else:
        buflen = args_abi_t.size_bound()
    buflen += 32
    buf_t = get_type_for_exact_size(buflen)
    buf = context.new_internal_variable(buf_t)
    args_ofst = buf + 28
    args_len = args_abi_t.size_bound() + 4
    abi_signature = fn_type.name + dst_tuple_t.abi_type.selector_name()
    pack_args = ["seq"]
    pack_args.append(["mstore", buf, util.abi_method_id(abi_signature)])
    if len(args) != 0:
        pack_args.append(abi_encode(buf + 32, args_as_tuple, context, bufsz=buflen))
    return buf, pack_args, args_ofst, args_len
def _unpack_returndata(buf, fn_type, call_kwargs, contract_address, context, expr):
    ast_return_t = fn_type.return_type
    if ast_return_t is None:
        return ["pass"], 0, 0
    return_t = new_type_to_old_type(ast_return_t)
    wrapped_return_t = calculate_type_for_external_return(return_t)
    abi_return_t = wrapped_return_t.abi_type
    min_return_size = abi_return_t.min_size()
    max_return_size = abi_return_t.size_bound()
    assert 0 < min_return_size <= max_return_size
    ret_ofst = buf
    ret_len = max_return_size
    encoding = Encoding.ABI
    buf = IRnode.from_list(
        buf,
        typ=wrapped_return_t,
        location=MEMORY,
        encoding=encoding,
        annotation=f"{expr.node_source_code} returndata buffer",
    )
    unpacker = ["seq"]
    if not call_kwargs.skip_contract_check:
        unpacker.append(["assert", ["ge", "returndatasize", min_return_size]])
    assert isinstance(wrapped_return_t, TupleType)
    if needs_clamp(wrapped_return_t, encoding):
        return_buf = context.new_internal_variable(wrapped_return_t)
        return_buf = IRnode.from_list(return_buf, typ=wrapped_return_t, location=MEMORY)
        unpacker.append(make_setter(return_buf, buf))
    else:
        return_buf = buf
    if call_kwargs.default_return_value is not None:
        override_value = wrap_value_for_external_return(call_kwargs.default_return_value)
        stomp_return_buffer = ["seq"]
        if not call_kwargs.skip_contract_check:
            stomp_return_buffer.append(_extcodesize_check(contract_address))
        stomp_return_buffer.append(make_setter(return_buf, override_value))
        unpacker = ["if", ["eq", "returndatasize", 0], stomp_return_buffer, unpacker]
    unpacker = ["seq", unpacker, return_buf]
    return unpacker, ret_ofst, ret_len
def _parse_kwargs(call_expr, context):
    from vyper.codegen.expr import Expr
    def _bool(x):
        assert x.value in (0, 1), "type checker missed this"
        return bool(x.value)
    call_kwargs = {kw.arg: Expr(kw.value, context).ir_node for kw in call_expr.keywords}
    ret = _CallKwargs(
        value=unwrap_location(call_kwargs.pop("value", IRnode(0))),
        gas=unwrap_location(call_kwargs.pop("gas", IRnode("gas"))),
        skip_contract_check=_bool(call_kwargs.pop("skip_contract_check", IRnode(0))),
        default_return_value=call_kwargs.pop("default_return_value", None),
    )
    if len(call_kwargs) != 0:
        raise TypeCheckFailure(f"Unexpected keyword arguments: {call_kwargs}")
    return ret
def _extcodesize_check(address):
    return ["assert", ["extcodesize", address]]
def ir_for_external_call(call_expr, context):
    from vyper.codegen.expr import Expr
    contract_address = Expr.parse_value_expr(call_expr.func.value, context)
    call_kwargs = _parse_kwargs(call_expr, context)
    args_ir = [Expr(x, context).ir_node for x in call_expr.args]
    assert isinstance(contract_address.typ, InterfaceType)
    fn_type = call_expr.func._metadata["type"]
    assert fn_type.min_arg_count <= len(args_ir) <= fn_type.max_arg_count
    ret = ["seq"]
    buf, arg_packer, args_ofst, args_len = _pack_arguments(fn_type, args_ir, context)
    ret_unpacker, ret_ofst, ret_len = _unpack_returndata(
        buf, fn_type, call_kwargs, contract_address, context, call_expr
    )
    ret += arg_packer
    if fn_type.return_type is None and not call_kwargs.skip_contract_check:
        ret.append(_extcodesize_check(contract_address))
    gas = call_kwargs.gas
    value = call_kwargs.value
    use_staticcall = fn_type.mutability in (StateMutability.VIEW, StateMutability.PURE)
    if context.is_constant():
        assert use_staticcall, "typechecker missed this"
    if use_staticcall:
        call_op = ["staticcall", gas, contract_address, args_ofst, args_len, buf, ret_len]
    else:
        call_op = ["call", gas, contract_address, value, args_ofst, args_len, buf, ret_len]
    ret.append(check_external_call(call_op))
    return_t = None
    if fn_type.return_type is not None:
        return_t = new_type_to_old_type(fn_type.return_type)
        ret.append(ret_unpacker)
    return IRnode.from_list(ret, typ=return_t, location=MEMORY)
def _build_adhoc_slice_node(sub: IRnode, start: IRnode, length: IRnode, context: Context) -> IRnode:
    assert length.is_literal, "typechecker failed"
    dst_typ = ByteArrayType(maxlen=length.value)
    np = context.new_internal_variable(dst_typ)
    if sub.value == "~calldata":
        node = [
            "seq",
            ["assert", ["le", ["add", start, length], "calldatasize"]],
            ["mstore", np, length],
            ["calldatacopy", np + 32, start, length],
            np,
        ]
    elif sub.value == "~selfcode":
        node = [
            "seq",
            ["assert", ["le", ["add", start, length], "codesize"]],
            ["mstore", np, length],
            ["codecopy", np + 32, start, length],
            np,
        ]
    else:
        assert sub.value == "~extcode" and len(sub.args) == 1
        node = [
            "with",
            "_extcode_address",
            sub.args[0],
            [
                "seq",
                [
                    "assert",
                    ["le", ["add", start, length], ["extcodesize", "_extcode_address"]],
                ],
                ["mstore", np, length],
                ["extcodecopy", "_extcode_address", np + 32, start, length],
                np,
            ],
        ]
    return IRnode.from_list(node, typ=ByteArrayType(length.value), location=MEMORY)
class Slice(_SimpleBuiltinFunction):
    @validate_inputs
    def build_IR(self, expr, args, kwargs, context):
        src, start, length = args
        if src.value in ADHOC_SLICE_NODE_MACROS:
            return _build_adhoc_slice_node(src, start, length, context)
        is_bytes32 = is_base_type(src.typ, "bytes32")
        if src.location is None:
            assert is_bytes32, src
            src = ensure_in_memory(src, context)
        with src.cache_when_complex("src") as (b1, src), start.cache_when_complex("start") as (
            b2,
            start,
        ), length.cache_when_complex("length") as (b3, length):
            if is_bytes32:
                src_maxlen = 32
            else:
                src_maxlen = src.typ.maxlen
            dst_maxlen = length.value if length.is_literal else src_maxlen
            buflen = dst_maxlen
            if src.location == STORAGE:
                buflen += 32
            assert isinstance(src.typ, ByteArrayLike) or is_bytes32
            if isinstance(src.typ, StringType):
                dst_typ = StringType(maxlen=dst_maxlen)
            else:
                dst_typ = ByteArrayType(maxlen=dst_maxlen)
            buf = context.new_internal_variable(ByteArrayType(buflen))
            dst = IRnode.from_list(buf, typ=dst_typ, location=MEMORY)
            dst_data = bytes_data_ptr(dst)
            if is_bytes32:
                src_len = 32
                src_data = src
            else:
                src_len = get_bytearray_length(src)
                src_data = bytes_data_ptr(src)
            if src.location == STORAGE:
                copy_src = IRnode.from_list(
                    ["add", src_data, ["div", start, 32]],
                    location=src.location,
                )
                copy_dst = IRnode.from_list(
                    ["sub", dst_data, ["mod", start, 32]], location=dst.location
                )
                copy_len = ["add", length, ["mul", 32, ["iszero", ["iszero", ["mod", start, 32]]]]]
                copy_maxlen = buflen
            else:
                copy_src = add_ofst(src_data, start)
                copy_dst = dst_data
                copy_len = length
                copy_maxlen = buflen
            do_copy = copy_bytes(
                copy_dst,
                copy_src,
                copy_len,
                copy_maxlen,
            )
            ret = [
                "seq",
                ["assert", ["le", ["add", start, length], src_len]],
                do_copy,
                ["mstore", dst, length],
                dst,
            ]
            ret = IRnode.from_list(ret, typ=dst_typ, location=MEMORY)
            return b1.resolve(b2.resolve(b3.resolve(ret)))
class RawCall(_SimpleBuiltinFunction):
    @validate_inputs
    def build_IR(self, expr, args, kwargs, context):
        to, data = args
        gas, value, outsize, delegate_call, static_call, revert_on_failure = (
            kwargs["gas"],
            kwargs["value"],
            kwargs["max_outsize"],
            kwargs["is_delegate_call"],
            kwargs["is_static_call"],
            kwargs["revert_on_failure"],
        )
        if delegate_call and static_call:
            raise ArgumentException(
                "Call may use one of `is_delegate_call` or `is_static_call`, not both", expr
            )
        if not static_call and context.is_constant():
            raise StateAccessViolation(
                f"Cannot make modifying calls from {context.pp_constancy()},"
                " use `is_static_call=True` to perform this action",
                expr,
            )
        eval_input_buf = ensure_in_memory(data, context)
        input_buf = eval_seq(eval_input_buf)
        output_node = IRnode.from_list(
            context.new_internal_variable(ByteArrayType(outsize)),
            typ=ByteArrayType(outsize),
            location=MEMORY,
        )
        bool_ty = BaseType("bool")
        if input_buf is None:
            call_ir = ["with", "arg_buf", eval_input_buf]
            input_buf = IRnode.from_list("arg_buf")
        else:
            call_ir = ["seq", eval_input_buf]
        common_call_args = [
            add_ofst(input_buf, 32),
            ["mload", input_buf],
            add_ofst(output_node, 32) if outsize else 0,
            outsize,
        ]
        if delegate_call:
            call_op = ["delegatecall", gas, to, *common_call_args]
        elif static_call:
            call_op = ["staticcall", gas, to, *common_call_args]
        else:
            call_op = ["call", gas, to, value, *common_call_args]
        call_ir += [call_op]
        if outsize:
            size = [
                "with",
                "_l",
                outsize,
                ["with", "_r", "returndatasize", ["if", ["gt", "_l", "_r"], "_r", "_l"]],
            ]
            store_output_size = [
                "with",
                "output_pos",
                output_node,
                ["seq", ["mstore", "output_pos", size], "output_pos"],
            ]
            bytes_ty = ByteArrayType(outsize)
            if revert_on_failure:
                typ = bytes_ty
                ret_ir = ["seq", check_external_call(call_ir), store_output_size]
            else:
                typ = TupleType([bool_ty, bytes_ty])
                ret_ir = [
                    "multi",
                    IRnode.from_list(call_ir, typ=bool_ty),
                    IRnode.from_list(store_output_size, typ=bytes_ty, location=MEMORY),
                ]
        else:
            if revert_on_failure:
                typ = None
                ret_ir = check_external_call(call_ir)
            else:
                typ = bool_ty
                ret_ir = call_ir
        return IRnode.from_list(ret_ir, typ=typ, location=MEMORY)
class Sqrt(_SimpleBuiltinFunction):
    @validate_inputs
    def build_IR(self, expr, args, kwargs, context):
        from vyper.builtin_functions.utils import generate_inline_function
        arg = args[0]
        sqrt_code = """
assert x >= 0.0
z: decimal = 0.0
if x == 0.0:
    z = 0.0
else:
    z = x / 2.0 + 0.5
    y: decimal = x
    for i in range(256):
        if z == y:
            break
        y = z
        z = (x / z + z) / 2.0
        """
        x_type = BaseType("decimal")
        placeholder_copy = ["pass"]
        if arg.value == "mload":
            new_var_pos = arg.args[0]
        else:
            new_var_pos = context.new_internal_variable(x_type)
            placeholder_copy = ["mstore", new_var_pos, arg]
        variables = {"x": VariableRecord(name="x", pos=new_var_pos, typ=x_type, mutable=False)}
        variables_2 = {"x": DecimalDefinition()}
        new_ctx, sqrt_ir = generate_inline_function(
            code=sqrt_code,
            variables=variables,
            variables_2=variables_2,
            memory_allocator=context.memory_allocator,
        )
        return IRnode.from_list(
            [
                "seq",
                placeholder_copy,
                sqrt_ir,
                new_ctx.vars["z"].pos,
            ],
            typ=BaseType("decimal"),
            location=MEMORY,
        )
class Stmt:
    def _assert_reason(self, test_expr, msg):
        if isinstance(msg, vy_ast.Name) and msg.id == "UNREACHABLE":
            return IRnode.from_list(["assert_unreachable", test_expr])
        try:
            tmp = self.context.constancy
            self.context.constancy = Constancy.Constant
            msg_ir = Expr(msg, self.context).ir_node
        finally:
            self.context.constancy = tmp
        def _get_last(ir):
            if len(ir.args) == 0:
                return ir.value
            return _get_last(ir.args[-1])
        if msg_ir.location != MEMORY:
            buf = self.context.new_internal_variable(msg_ir.typ)
            instantiate_msg = make_byte_array_copier(buf, msg_ir)
        else:
            buf = _get_last(msg_ir)
            if not isinstance(buf, int):
                raise CompilerPanic(f"invalid bytestring {buf}\n{self}")
            instantiate_msg = msg_ir
        method_id = util.abi_method_id("Error(string)")
        assert buf >= 36, "invalid buffer"
        _runtime_length = ["mload", buf]
        revert_seq = [
            "seq",
            instantiate_msg,
            zero_pad(buf),
            ["mstore", buf - 64, method_id],
            ["mstore", buf - 32, 0x20],
            ["revert", buf - 36, ["add", 4 + 32 + 32, ["ceil32", _runtime_length]]],
        ]
        if test_expr is not None:
            ir_node = ["if", ["iszero", test_expr], revert_seq]
        else:
            ir_node = revert_seq
        return IRnode.from_list(ir_node)
class Expr:
    def parse_Attribute(self):
        typ = self.expr._metadata.get("type")
        if typ is not None:
            typ = new_type_to_old_type(typ)
        if isinstance(typ, EnumType):
            assert typ.name == self.expr.value.id
            enum_id = typ.members[self.expr.attr]
            value = 2 ** enum_id
            return IRnode.from_list(value, typ=typ)
        if self.expr.attr == "balance":
            addr = Expr.parse_value_expr(self.expr.value, self.context)
            if is_base_type(addr.typ, "address"):
                if (
                    isinstance(self.expr.value, vy_ast.Name)
                    and self.expr.value.id == "self"
                    and version_check(begin="istanbul")
                ):
                    seq = ["selfbalance"]
                else:
                    seq = ["balance", addr]
                return IRnode.from_list(seq, typ=BaseType("uint256"))
        elif self.expr.attr == "codesize" or self.expr.attr == "is_contract":
            addr = Expr.parse_value_expr(self.expr.value, self.context)
            if is_base_type(addr.typ, "address"):
                if self.expr.attr == "codesize":
                    if self.expr.get("value.id") == "self":
                        eval_code = ["codesize"]
                    else:
                        eval_code = ["extcodesize", addr]
                    output_type = "uint256"
                else:
                    eval_code = ["gt", ["extcodesize", addr], 0]
                    output_type = "bool"
                return IRnode.from_list(eval_code, typ=BaseType(output_type))
        elif self.expr.attr == "codehash":
            addr = Expr.parse_value_expr(self.expr.value, self.context)
            if not version_check(begin="constantinople"):
                raise EvmVersionException(
                    "address.codehash is unavailable prior to constantinople ruleset", self.expr
                )
            if is_base_type(addr.typ, "address"):
                return IRnode.from_list(["extcodehash", addr], typ=BaseType("bytes32"))
        elif self.expr.attr == "code":
            addr = Expr.parse_value_expr(self.expr.value, self.context)
            if is_base_type(addr.typ, "address"):
                if addr.value == "address":
                    return IRnode.from_list(["~selfcode"], typ=ByteArrayType(0))
                return IRnode.from_list(["~extcode", addr], typ=ByteArrayType(0))
        elif isinstance(self.expr.value, vy_ast.Name) and self.expr.value.id == "self":
            type_ = self.expr._metadata["type"]
            var = self.context.globals[self.expr.attr]
            return IRnode.from_list(
                type_.position.position,
                typ=var.typ,
                location=STORAGE,
                annotation="self." + self.expr.attr,
            )
        elif (
            isinstance(self.expr.value, vy_ast.Name) and self.expr.value.id in ENVIRONMENT_VARIABLES
        ):
            key = f"{self.expr.value.id}.{self.expr.attr}"
            if key == "msg.sender":
                return IRnode.from_list(["caller"], typ="address")
            elif key == "msg.data":
                return IRnode.from_list(["~calldata"], typ=ByteArrayType(0))
            elif key == "msg.value" and self.context.is_payable:
                return IRnode.from_list(["callvalue"], typ=BaseType("uint256"))
            elif key == "msg.gas":
                return IRnode.from_list(["gas"], typ="uint256")
            elif key == "block.difficulty":
                return IRnode.from_list(["difficulty"], typ="uint256")
            elif key == "block.timestamp":
                return IRnode.from_list(["timestamp"], typ=BaseType("uint256"))
            elif key == "block.coinbase":
                return IRnode.from_list(["coinbase"], typ="address")
            elif key == "block.number":
                return IRnode.from_list(["number"], typ="uint256")
            elif key == "block.gaslimit":
                return IRnode.from_list(["gaslimit"], typ="uint256")
            elif key == "block.basefee":
                return IRnode.from_list(["basefee"], typ="uint256")
            elif key == "block.prevhash":
                return IRnode.from_list(["blockhash", ["sub", "number", 1]], typ="bytes32")
            elif key == "tx.origin":
                return IRnode.from_list(["origin"], typ="address")
            elif key == "tx.gasprice":
                return IRnode.from_list(["gasprice"], typ="uint256")
            elif key == "chain.id":
                if not version_check(begin="istanbul"):
                    raise EvmVersionException(
                        "chain.id is unavailable prior to istanbul ruleset", self.expr
                    )
                return IRnode.from_list(["chainid"], typ="uint256")
        else:
            sub = Expr(self.expr.value, self.context).ir_node
            if isinstance(sub.typ, InterfaceType):
                return sub
            if isinstance(sub.typ, StructType) and self.expr.attr in sub.typ.members:
                return get_element_ptr(sub, self.expr.attr)
def make_return_stmt(ir_val: IRnode, stmt: Any, context: Context) -> Optional[IRnode]:
    sig = context.sig
    jump_to_exit = ["exit_to", f"_sym_{sig.exit_sequence_label}"]
    if context.return_type is None:
        if stmt.value is not None:
            return None
    else:
        check_assign(dummy_node_for_type(context.return_type), ir_val)
    def finalize(fill_return_buffer):
        fill_return_buffer = IRnode.from_list(
            fill_return_buffer, annotation=f"fill return buffer {sig._ir_identifier}"
        )
        cleanup_loops = "cleanup_repeat" if context.forvars else "seq"
        return IRnode.from_list(["seq", fill_return_buffer, cleanup_loops, jump_to_exit])
    if context.return_type is None:
        jump_to_exit += ["return_pc"]
        return finalize(["seq"])
    if context.is_internal:
        dst = IRnode.from_list(["return_buffer"], typ=context.return_type, location=MEMORY)
        fill_return_buffer = make_setter(dst, ir_val)
        jump_to_exit += ["return_pc"]
        return finalize(fill_return_buffer)
    else:
        external_return_type = calculate_type_for_external_return(context.return_type)
        maxlen = external_return_type.abi_type.size_bound()
        can_skip_encode = (
            abi_encoding_matches_vyper(ir_val.typ)
            and ir_val.location == MEMORY
            and not needs_clamp(ir_val.typ, ir_val.encoding)
        )
        if can_skip_encode:
            assert ir_val.typ.memory_bytes_required == maxlen
            jump_to_exit += [ir_val, maxlen]
            return finalize(["pass"])
        ir_val = wrap_value_for_external_return(ir_val)
        return_buffer_ofst = context.new_internal_variable(get_type_for_exact_size(maxlen))
