                    ["sub", dst_data, ["mod", start, 32]], location=dst.location
                )
                copy_len = ["add", length, ["mul", 32, ["iszero", ["iszero", ["mod", start, 32]]]]]
                copy_maxlen = buflen
            else:
                copy_src = add_ofst(src_data, start)
                copy_dst = dst_data
                copy_len = length
                copy_maxlen = buflen
            do_copy = copy_bytes(
                copy_dst,
                copy_src,
                copy_len,
                copy_maxlen,
            )
            ret = [
                "seq",
                ["assert", ["le", ["add", start, length], src_len]],
                do_copy,
                ["mstore", dst, length],
                dst,
            ]
            ret = IRnode.from_list(ret, typ=dst_typ, location=MEMORY)
            return b1.resolve(b2.resolve(b3.resolve(ret)))
class RawCall(_SimpleBuiltinFunction):
    @validate_inputs
    def build_IR(self, expr, args, kwargs, context):
        to, data = args
        gas, value, outsize, delegate_call, static_call, revert_on_failure = (
            kwargs["gas"],
            kwargs["value"],
            kwargs["max_outsize"],
            kwargs["is_delegate_call"],
            kwargs["is_static_call"],
            kwargs["revert_on_failure"],
        )
        if delegate_call and static_call:
            raise ArgumentException(
                "Call may use one of `is_delegate_call` or `is_static_call`, not both", expr
            )
        if not static_call and context.is_constant():
            raise StateAccessViolation(
                f"Cannot make modifying calls from {context.pp_constancy()},"
                " use `is_static_call=True` to perform this action",
                expr,
            )
        eval_input_buf = ensure_in_memory(data, context)
        input_buf = eval_seq(eval_input_buf)
        output_node = IRnode.from_list(
            context.new_internal_variable(ByteArrayType(outsize)),
            typ=ByteArrayType(outsize),
            location=MEMORY,
        )
        bool_ty = BaseType("bool")
        if input_buf is None:
            call_ir = ["with", "arg_buf", eval_input_buf]
            input_buf = IRnode.from_list("arg_buf")
        else:
            call_ir = ["seq", eval_input_buf]
        common_call_args = [
            add_ofst(input_buf, 32),
            ["mload", input_buf],
            add_ofst(output_node, 32) if outsize else 0,
            outsize,
        ]
        if delegate_call:
            call_op = ["delegatecall", gas, to, *common_call_args]
        elif static_call:
            call_op = ["staticcall", gas, to, *common_call_args]
        else:
            call_op = ["call", gas, to, value, *common_call_args]
        call_ir += [call_op]
        if outsize:
            size = [
                "with",
                "_l",
                outsize,
                ["with", "_r", "returndatasize", ["if", ["gt", "_l", "_r"], "_r", "_l"]],
            ]
            store_output_size = [
                "with",
                "output_pos",
                output_node,
                ["seq", ["mstore", "output_pos", size], "output_pos"],
            ]
            bytes_ty = ByteArrayType(outsize)
            if revert_on_failure:
                typ = bytes_ty
                ret_ir = ["seq", check_external_call(call_ir), store_output_size]
            else:
                typ = TupleType([bool_ty, bytes_ty])
                ret_ir = [
                    "multi",
                    IRnode.from_list(call_ir, typ=bool_ty),
                    IRnode.from_list(store_output_size, typ=bytes_ty, location=MEMORY),
                ]
        else:
            if revert_on_failure:
                typ = None
                ret_ir = check_external_call(call_ir)
            else:
                typ = bool_ty
                ret_ir = call_ir
        return IRnode.from_list(ret_ir, typ=typ, location=MEMORY)
def _optimize_arith(binop, args, ann, parent_op):
    fn, symb, unsigned = arith[binop]
    def _int(x, unsigned=unsigned):
        return _evm_int(x, unsigned=unsigned)
    def _wrap(x, unsigned=unsigned):
        x %= 2 ** 256
        if not unsigned:
            x = unsigned_to_signed(x, 256, strict=True)
        return x
    new_ann = None
    if ann is not None:
        l_ann = args[0].annotation or str(args[0])
        r_ann = args[1].annotation or str(args[1])
        new_ann = l_ann + symb + r_ann
        new_ann = f"{ann} ({new_ann})"
    if _is_int(args[0]) and _is_int(args[1]):
        left, right = _int(args[0]), _int(args[1])
        new_val = fn(left, right)
        new_val = _wrap(new_val)
        return new_val, [], new_ann
    new_val = None
    new_args = None
    is_truthy = parent_op in {"if", "assert", "iszero"}
    def _conservative_eq(x, y):
        return x.args == y.args == [] and x.value == y.value and not x.is_complex_ir
    if binop in COMMUTATIVE_OPS and _is_int(args[0]):
        args = [args[1], args[0]]
    if binop in COMPARISON_OPS and _is_int(args[0]):
        binop = _flip_comparison_op(binop)
        args = [args[1], args[0]]
    if binop in {"add", "sub", "xor", "or"} and _int(args[1]) == 0:
        new_val = args[0].value
        new_args = args[0].args
    elif binop in {"sub", "xor"} and _conservative_eq(args[0], args[1]):
        new_val = 0
        new_args = []
    elif binop in {"mul", "div", "sdiv", "mod", "smod", "and"} and _int(args[1]) == 0:
        new_val = 0
        new_args = []
    elif binop in {"mod", "smod"} and _int(args[1]) == 1:
        new_val = 0
        new_args = []
    elif binop in {"mul", "div", "sdiv"} and _int(args[1]) == 1:
        new_val = args[0].value
        new_args = args[0].args
    elif binop in {"mul", "sdiv"} and _int(args[1], SIGNED) == -1:
        new_val = "sub"
        new_args = [0, args[0]]
    elif binop in {"mod", "div", "mul"} and _is_int(args[1]) and is_power_of_two(_int(args[1])):
        assert unsigned == UNSIGNED, "something's not right."
        if binop == "mod":
            new_val = "and"
            new_args = [args[0], _int(args[1]) - 1]
        if binop == "div" and version_check(begin="constantinople"):
            new_val = "shr"
            new_args = [int_log2(_int(args[1])), args[0]]
        if binop == "mul" and version_check(begin="constantinople"):
            new_val = "shl"
            new_args = [int_log2(_int(args[1])), args[0]]
    elif binop in {"and", "or", "xor"} and _int(args[1]) == 2 ** 256 - 1:
        if binop == "and":
            new_val = args[0].value
            new_args = args[0].args
        elif binop == "xor":
            new_val = "not"
            new_args = [args[0]]
        elif binop == "or":
            new_val = args[1].value
            new_args = []
        else:
            raise CompilerPanic("unreachable")
    elif is_truthy:
        if binop == "eq":
            if _int(args[1], UNSIGNED) == 2 ** 256 - 1:
                new_val = "iszero"
                new_args = [["not", args[0]]]
            else:
                new_val = "iszero"
                new_args = [["sub", *args]]
        elif binop in {"sgt", "gt", "slt", "lt"} and _is_int(args[1]):
            assert unsigned == (not binop.startswith("s")), "signed opcodes should start with s"
            op_is_gt = binop.endswith("gt")
            rhs = _int(args[1])
            new_rhs = rhs + 1 if op_is_gt else rhs - 1
            if _wrap(new_rhs) != new_rhs:
                new_val = 0
                new_args = []
            else:
                new_val = binop.replace("t", "e")
                new_args = [args[0], new_rhs]
        elif binop == "or" and _is_int(args[1]):
            if _int(args[1]) != 0:
                new_val = 1
                new_args = []
    elif binop in {"eq", "le"} and _int(args[1]) == 0:
        new_val = "iszero"
        new_args = [args[0]]
    elif binop == "ge" and _int(args[1]) == 0:
        new_val = 1
        new_args = []
    elif binop == "lt":
        if _int(args[1]) == 0:
            new_val = 0
            new_args = []
        if _int(args[1]) == 1:
            new_val = "iszero"
            new_args = [args[0]]
    elif binop == "gt" and _int(args[1]) == 0:
        new_val = "iszero"
        new_args = [["iszero", args[0]]]
    rollback = (
        new_val is None
        or (args[0].is_complex_ir and not _deep_contains(new_args, args[0]))
        or (args[1].is_complex_ir and not _deep_contains(new_args, args[1]))
    )
    if rollback:
        return None
    return new_val, new_args, new_ann
def make_return_stmt(ir_val: IRnode, stmt: Any, context: Context) -> Optional[IRnode]:
    sig = context.sig
    jump_to_exit = ["exit_to", f"_sym_{sig.exit_sequence_label}"]
    if context.return_type is None:
        if stmt.value is not None:
            return None
    else:
        check_assign(dummy_node_for_type(context.return_type), ir_val)
    def finalize(fill_return_buffer):
        fill_return_buffer = IRnode.from_list(
            fill_return_buffer, annotation=f"fill return buffer {sig._ir_identifier}"
        )
        cleanup_loops = "cleanup_repeat" if context.forvars else "seq"
        return IRnode.from_list(["seq", fill_return_buffer, cleanup_loops, jump_to_exit])
    if context.return_type is None:
        jump_to_exit += ["return_pc"]
        return finalize(["seq"])
    if context.is_internal:
        dst = IRnode.from_list(["return_buffer"], typ=context.return_type, location=MEMORY)
        fill_return_buffer = make_setter(dst, ir_val)
        jump_to_exit += ["return_pc"]
        return finalize(fill_return_buffer)
    else:
        external_return_type = calculate_type_for_external_return(context.return_type)
        maxlen = external_return_type.abi_type.size_bound()
        can_skip_encode = (
            abi_encoding_matches_vyper(ir_val.typ)
            and ir_val.location == MEMORY
            and not needs_clamp(ir_val.typ, ir_val.encoding)
        )
        if can_skip_encode:
            assert ir_val.typ.memory_bytes_required == maxlen
            jump_to_exit += [ir_val, maxlen]
            return finalize(["pass"])
        ir_val = wrap_value_for_external_return(ir_val)
        return_buffer_ofst = context.new_internal_variable(get_type_for_exact_size(maxlen))
        return_len = abi_encode(return_buffer_ofst, ir_val, context, returns_len=True, bufsz=maxlen)
        jump_to_exit += [return_buffer_ofst, return_len]
        return finalize(["pass"])
MEMORY = AddrSpace("memory", 32, "mload", "mstore")
STORAGE = AddrSpace("storage", 1, "sload", "sstore")

