class _GlancesCurses(object):
    def __catch_key(self, return_to_browser=False):
        self.pressedkey = self.get_key(self.term_window)
        for hotkey in self._hotkeys:
            if self.pressedkey == ord(hotkey) and 'switch' in self._hotkeys[hotkey]:
                setattr(self.args,
                        self._hotkeys[hotkey]['switch'],
                        not getattr(self.args,
                                    self._hotkeys[hotkey]['switch']))
            if self.pressedkey == ord(hotkey) and 'sort_key' in self._hotkeys[hotkey]:
                glances_processes.set_sort_key(self._hotkeys[hotkey]['sort_key'],
                                               self._hotkeys[hotkey]['sort_key'] == 'auto')
        if self.pressedkey == ord('\n'):
            self.edit_filter = not self.edit_filter
        elif self.pressedkey == ord('4'):
            self.args.full_quicklook = not self.args.full_quicklook
            if self.args.full_quicklook:
                self.enable_fullquicklook()
            else:
                self.disable_fullquicklook()
        elif self.pressedkey == ord('5'):
            self.args.disable_top = not self.args.disable_top
            if self.args.disable_top:
                self.disable_top()
            else:
                self.enable_top()
        elif self.pressedkey == ord('e'):
            self.args.enable_process_extended = not self.args.enable_process_extended
            if not self.args.enable_process_extended:
                glances_processes.disable_extended()
            else:
                glances_processes.enable_extended()
        elif self.pressedkey == ord('E'):
            glances_processes.process_filter = None
        elif self.pressedkey == ord('f'):
            self.args.disable_fs = not self.args.disable_fs
            self.args.disable_folders = not self.args.disable_folders
        elif self.pressedkey == ord('k'):
            self.kill_process = not self.kill_process
        elif self.pressedkey == ord('w'):
            glances_events.clean()
        elif self.pressedkey == ord('x'):
            glances_events.clean(critical=True)
        elif self.pressedkey == ord('z'):
            self.args.disable_process = not self.args.disable_process
            if self.args.disable_process:
                glances_processes.disable()
            else:
                glances_processes.enable()
        elif self.pressedkey == curses.KEY_LEFT:
            next_sort = (self.loop_position() - 1) % len(self._sort_loop)
            glances_processes.set_sort_key(self._sort_loop[next_sort], False)
        elif self.pressedkey == curses.KEY_RIGHT:
            next_sort = (self.loop_position() + 1) % len(self._sort_loop)
            glances_processes.set_sort_key(self._sort_loop[next_sort], False)
        elif self.pressedkey == curses.KEY_UP or self.pressedkey == 65:
            if self.args.cursor_position > 0:
                self.args.cursor_position -= 1
        elif self.pressedkey == curses.KEY_DOWN or self.pressedkey == 66:
            if self.args.cursor_position < glances_processes.processes_count:
                self.args.cursor_position += 1
        elif self.pressedkey == ord('\x1b') or self.pressedkey == ord('q'):
            if return_to_browser:
                logger.info("Stop Glances client and return to the browser")
            else:
                logger.info(
                    "Stop Glances (keypressed: {})".format(self.pressedkey))
        elif self.pressedkey == curses.KEY_F5:
            pass
        return self.pressedkey
class Plugin(GlancesPlugin):
    @GlancesPlugin._check_decorator
    @GlancesPlugin._log_result_decorator
    def update(self):
        """Update sensors stats using the input method."""
        stats = self.get_init_value()
        if self.input_method == 'local':
            stats = []
            try:
                temperature = self.__set_type(self.glancesgrabsensors.get('temperature_core'),
                                              'temperature_core')
            except Exception as e:
                logger.error("Cannot grab sensors temperatures (%s)" % e)
            else:
                stats.extend(temperature)
            try:
                fan_speed = self.__set_type(self.glancesgrabsensors.get('fan_speed'),
                                            'fan_speed')
            except Exception as e:
                logger.error("Cannot grab FAN speed (%s)" % e)
            else:
                stats.extend(fan_speed)
            try:
                hddtemp = self.__set_type(self.hddtemp_plugin.update(),
                                          'temperature_hdd')
            except Exception as e:
                logger.error("Cannot grab HDD temperature (%s)" % e)
            else:
                stats.extend(hddtemp)
            try:
                batpercent = self.__set_type(self.batpercent_plugin.update(),
                                             'battery')
            except Exception as e:
                logger.error("Cannot grab battery percent (%s)" % e)
            else:
                stats.extend(batpercent)
        elif self.input_method == 'snmp':
            pass
        self.stats = self.get_init_value()
        for stat in stats:
            if self.is_hide(stat["label"].lower()):
                continue
            alias = self.has_alias(stat["label"].lower())
            if alias:
                stat["label"] = alias
            self.stats.append(stat)
        return self.stats
