        "gs",
        "-q",
        "-g%dx%d" % size,
        "-r%fx%f" % res,
        "-dBATCH",
        "-dNOPAUSE",
        "-dSAFER",
        f"-sDEVICE={device}",
        f"-sOutputFile={outfile}",
        "-c",
        f"{-bbox[0]} {-bbox[1]} translate",
        "-f",
        infile,
        "-c",
        "showpage",
    ]
