            overlays = []
        assert isinstance(default_settings, dict)
        self._map = HierarchicalChainMap({}, default_settings)
        self.load_overlays(overlays)
        self._dirty = False
        self._dirty_time = 0
        self._last_config_hash = None
        self._last_effective_hash = None
