                try:
                    config = yaml.load_from_file(file=f)
                    mtime = self.last_modified
                except YAMLError as e:
                    details = str(e)
                    if hasattr(e, "problem_mark"):
                        line = e.problem_mark.line
                        column = e.problem_mark.column
                    else:
                        line = None
                        column = None
                    raise InvalidYaml(
                        self._configfile,
                        details=details,
                        line=line,
                        column=column,
                    )
