            if not self._dirty and not force:
                return False
            try:
                with atomic_write(
                    self._configfile,
                    mode="wt",
                    prefix="octoprint-config-",
                    suffix=".yaml",
                    permissions=0o600,
                    max_permissions=0o666,
                ) as configFile:
                    yaml.save_to_file(self._map.top_map, file=configFile)
