        if not path:
            if error_on_path:
                raise NoSuchSettingsPath()
            return
        chain = self._map.with_config_defaults(config=config, defaults=defaults)
        try:
            with self._lock:
                chain.del_by_path(path)
                self._mark_dirty()
        except KeyError:
            if error_on_path:
                raise NoSuchSettingsPath()
            pass
