                try:
                    chain.del_by_path(path)
                    self._mark_dirty()
                    self._path_modified(path, current, value)
                except KeyError:
                    if error_on_path:
                        raise NoSuchSettingsPath()
                    pass
            elif (
                force
                or (not in_local and in_defaults and default_value != value)
                or (in_local and current != value)
            ):
                chain.set_by_path(path, value)
                self._mark_dirty()
                self._path_modified(path, current, value)
