        pos += 1
        initial += 1
        offset += 1
        adjustTab = False
        spaceAfterMarker = True
    elif second_char_code == 0x09:
        spaceAfterMarker = True
        if (state.bsCount[startLine] + offset) % 4 == 3:
            pos += 1
            initial += 1
            offset += 1
            adjustTab = False
        else:
            adjustTab = True
    else:
        spaceAfterMarker = False
