    def full_clean(self, *args, **kwargs):
        if not self.slug:
            allow_unicode = getattr(settings, "WAGTAIL_ALLOW_UNICODE_SLUGS", True)
            base_slug = slugify(self.title, allow_unicode=allow_unicode)
            if base_slug:
