	else:
		frappe.throw(_('Please set script URL on Gsuite Settings'))
class GoogleContacts(Document):
	def get_access_token(self):
		google_settings = frappe.get_doc("Google Settings")
		if not google_settings.enable:
			frappe.throw(_("Google Contacts Integration is disabled."))
		if not self.refresh_token:
			button_label = frappe.bold(_('Allow Google Contacts Access'))
			raise frappe.ValidationError(_("Click on {0} to generate Refresh Token.").format(button_label))
		data = {
			"client_id": google_settings.client_id,
			"client_secret": google_settings.get_password(fieldname="client_secret", raise_exception=False),
			"refresh_token": self.get_password(fieldname="refresh_token", raise_exception=False),
			"grant_type": "refresh_token",
			"scope": SCOPES
		}
		try:
			r = requests.post("https://www.googleapis.com/oauth2/v4/token", data=data).json()
		except requests.exceptions.HTTPError:
			button_label = frappe.bold(_('Allow Google Contacts Access'))
			frappe.throw(_("Something went wrong during the token generation. Click on {0} to generate a new one.").format(button_label))
		return r.get("access_token")
def split_emails(txt):
	email_list = []
	s = re.sub(r'[\t\n\r]', ' ', cstr(txt))
	for email in re.split('''[,\\n](?=(?:[^"]|"[^"]*")*$)''', s):
		email = strip(cstr(email))
		if email:
			email_list.append(email)
	return email_list
def get_request_site_address(full_address=False):
	return get_url(full_address=full_address)

def render_description(text, content_type):
    """Render Description field to HTML"""
    if re.match(r'^.+(\n {8}.*)+\n?$', text):
        text = re.sub(r'^ {8}', '', text, flags=re.MULTILINE)
    if content_type == 'text/x-rst':
        html = publish_parts(
            text, writer_name='html',
            settings_overrides={'syntax_highlight': 'short'})['html_body']
    elif content_type == 'text/markdown':
        html = markdown(text, extensions=[GithubFlavoredMarkdownExtension()])
    else:
        html = format_html('<pre>{}</pre>', text)
    return mark_safe(html)

